    let tabBar = UITabBarController()
    tabBar.viewControllers = [
        HomeViewController(),      // SceneDelegate 被迫 import Home
        FollowingViewController(), // 与 Feature 模块产生硬依赖
        ProfileViewController()
    ]
    window?.rootViewController = tabBar
}
```

